const input =
  $json.request_id
    ? $json
    : ($json.body && $json.body.request_id)
      ? $json.body
      : $json;

const supportedAuthModesV1 = ['none'];

function errorResult(code, message) {
  return [{
    json: {
      adapter_status: 'error',
      validation_status: 'invalid',
      request_id: input.request_id || null,
      source_component: input.source_component || null,
      webhook_url: input.webhook_url || null,
      auth_mode: input.auth?.mode || 'none',
      headers: input.headers || {},
      query: input.query || {},
      payload: input.payload === undefined ? null : input.payload,
      status_code: null,
      response_body: null,
      manual_review_required: true,
      error_code: code,
      error_message: message,
      next_action: 'route_to_manual_review_or_error_log',
      status_log_event: 'webhook_send_validation_error',
      downstream_components: ['C5-E', 'C6-G', 'C5-W'],
      original_input: input
    }
  }];
}

if (!input.request_id) {
  return errorResult('MISSING_REQUEST_ID', 'request_id is required.');
}

if (!input.webhook_url) {
  return errorResult('MISSING_WEBHOOK_URL', 'webhook_url is required before ADP-WEBHOOK-SEND can send the request.');
}

const authMode = input.auth?.mode || 'none';

if (!supportedAuthModesV1.includes(authMode)) {
  return errorResult('AUTH_MODE_NOT_SUPPORTED_V1', `Auth mode ${authMode} is not supported in ADP-WEBHOOK-SEND v1.`);
}

if (input.payload === undefined || input.payload === null) {
  return errorResult('MISSING_PAYLOAD', 'payload is required before ADP-WEBHOOK-SEND can send the webhook.');
}

return [{
  json: {
    adapter_status: 'ready',
    validation_status: 'valid',
    request_id: input.request_id,
    source_component: input.source_component || null,
    method: 'POST',
    webhook_url: input.webhook_url,
    auth_mode: authMode,
    headers: input.headers || {},
    query: input.query || {},
    payload: input.payload,
    routing_options: input.routing_options || {},
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: 'send_outbound_webhook',
    status_log_event: 'webhook_send_request_validated',
    original_input: input
  }
}];

const response = $json;

return [{
  json: {
    adapter_status: 'success',
    validation_status: 'valid',
    request_id: response.request_id || response.json?.request_id || null,
    method: 'POST',
    webhook_url: response.url || null,
    status_code: 200,
    response_body: response,
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: 'return_webhook_send_success',
    status_log_event: 'webhook_send_success',
    downstream_components: ['C5-W']
  }
}];
